// План specs/seo.md, 1.2 (кейс SEO-02). Гость, только GET-запросы к лендингу https://techory.ai. @prod-safe
import { test, expect } from '@playwright/test';

test.describe('SEO — sitemap.xml (#f576f6d3)', () => {
  test('every page listed in sitemap.xml opens with status 200 #f576f6d3 @desktop @prod-safe', async ({ request }) => {
    const body = await (await request.get('https://techory.ai/sitemap.xml')).text();
    const locs = [...body.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1].trim());
    expect(locs.length).toBeGreaterThanOrEqual(3);

    for (const loc of locs) {
      const res = await request.get(loc);
      expect(res.status(), loc).toBe(200);
    }
  });
});
